export function beforeUpperStoneDepth(name,source) {
  name=name.split('/').at(-1);
  if(!Object.hasOwn(changes,name))return source;
  source=String(source);
  for(const [added,original]of [...changes[name]].reverse()){
    assert(added.length>0);
    assert.equal(source.split(added).length,2,`Exact courtyard upper stone-depth delta required in ${name}`);
    source=source.replace(added,original);
  }
  return source;
}
